**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int sumaCyfr(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    int maxSuma = sumaCyfr(tab[0]);
    int maxLiczba = tab[0];
    for (int i = 1; i < (int)tab.size(); i++) {
        int sc = sumaCyfr(tab[i]);
        if (sc > maxSuma) {
            maxSuma = sc;
            maxLiczba = tab[i];
        }
    }
    cout << "Liczba o max sumie cyfr: " << maxLiczba
         << " (suma cyfr: " << maxSuma << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Klasyczny skan liniowy, ale zamiast porownywac same liczby, porownujemy wartosc pochodna (sume cyfr). Funkcja sumaCyfr uzywa petli mod/div.

Weryfikacja:
- 145: 1+4+5=10, 390: 3+9+0=12, 278: 2+7+8=17, 56: 5+6=11, 812: 8+1+2=11
- 999: 9+9+9=27, 430: 4+3+0=7, 67: 6+7=13, 204: 2+0+4=6, 555: 5+5+5=15
- Max suma cyfr = 27 dla liczby 999.
